{
  "status": "answered",
  "claims": [
    {
      "text": "يجب أن يتم الإخطار قبل الإنهاء بشهرين إذا لم تتجاوز مدة الخدمة المتصلة للعامل لدي صاحب العمل عشر سنوات، وقبل الإنهاء بثلاثة أشهر إذا زادت هذه المدة على عشر سنوات.",
      "source_ids": ["S3"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "العامل يستحق إجازة سنوية مدتها 21 يوماً بأجر كامل بعد سنة من الخدمة، و30 يوماً بعد عشر سنوات من الخدمة لدى صاحب عمل أو أكثر، و30 يوماً أيضاً للعامل الذي تجاوز سن الخمسين.",
      "source_ids": ["S1"]
    },
    {
      "text": "تزيد مدة الإجازة السنوية سبعة أيام للعمال الذين يعملون في الأعمال الشاقة أو الخطرة أو المضرة بالصحة أو في المناطق النائية.",
      "source_ids": ["S1"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "تقضي المحكمة العمالية - بصفة مستعجلة - وبحكم واجب النفاذ بتعويض مؤقت للعامل يعادل أجره الشامل لمدة اثني عشر شهراً إذا جاوزت مدة عمله سنة كاملة، فإن كانت أقل من ذلك كان التعويض المؤقت بقدر أجره الشامل عن مدة عمله.",
      "source_ids": ["S4"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "يجب تنظيم العمل بالمنشأة بحيث يحصل كل عامل على راحة أسبوعية لا تقل عن أربع وعشرين ساعة كاملة بعد ستة أيام عمل متصلة على الأكثر، وفي جميع الأحوال تكون الراحة الأسبوعية مدفوعة الأجر.",
      "source_ids": ["S4"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "صاحب العمل ملزم بدفع مبلغ يعادل أجر العامل عن مدة المهلة القانونية أو الجزء الباقي منها.",
      "source_ids": ["S4"]
    },
    {
      "text": "المدة القانونية هي شهرين في حال إنهاء العقد دون سابق إنذار.",
      "source_ids": ["S4"]
    },
    {
      "text": "المبلغ المستحق يحسب على أساس أجر العامل.",
      "source_ids": ["S4"]
    },
    {
      "text": "صاحب العمل ملزم بتحمل الأعباء والالتزامات المترتبة على إنهاء العقد دون سابق إنذار.",
      "source_ids": ["S4"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "لا يجوز لصاحب العمل أن يقتطع من أجر العامل أكثر من (10%) وفاء لما يكون قد أقرضه من مال أثناء سريان العقد أو أن يتقاضى أية فائدة عن هذه القروض.",
      "source_ids": ["S4"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "النضال النقابي أو تقديم الشكاوى ضد صاحب العمل لا يعتبران من الأسباب المشروعة والكافية للإنهاء.",
      "source_ids": ["S3"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "للتاريخ التحاق العامل بالخدمة وتاريخ انتهائها، ونوع العمل الذي كان يؤديه، والمزايا التي كان يحصل عليها.",
      "source_ids": ["S1"]
    },
    {
      "text": "للعامل أن يحصل من صاحب العمل دون مقابل على شهادة بتحديد خبرته وكفاءته المهنية.",
      "source_ids": ["S1"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
  "claims": [
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل الإنذار.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل الخصم من الأجر.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل تأجيل موعد استحقاق العلاوة السنوية لمدة لا تجاوز ثلاثة أشهر.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل الحرمان من جزء من العلاوة السنوية بما لا يجاوز نصفها.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل تأجيل الترقية عند استحقاقها لمدة لا تزيد على سنة.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل خفض الأجر بمقدار علاوة على الأكثر.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل الخفض إلى وظيفة في الدرجة الأدنى مباشرة دون إخلال بقيمة الأجر الذي كان يتقاضاه.",
      "source_ids": ["S1"]
    },
    {
      "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل تشمل الفصل من الخدمة وفقا لأحكام هذا القانون.",
      "source_ids": ["S1"]
    }
  ],
  "clarification_question": null
}

